#ifndef EXCELTOCSVCONVERTER_H
#define EXCELTOCSVCONVERTER_H

#include <QMainWindow>
#include <QThread>

QT_BEGIN_NAMESPACE
class QPushButton;
class QLabel;
class QTextEdit;
class QProgressBar;
QT_END_NAMESPACE

class ConversionWorker : public QObject
{
    Q_OBJECT

public:
    ConversionWorker(const QString &dirPath);

public slots:
    void process();

signals:
    void progress(int value);
    void log(const QString &message);
    void finished();
    void error(const QString &error);

private:
    QString m_dirPath;
    bool convertExcelToCsv(const QString &excelPath, const QString &csvPath);
};

class ExcelToCsvConverter : public QMainWindow
{
    Q_OBJECT

public:
    ExcelToCsvConverter(QWidget *parent = nullptr);
    ~ExcelToCsvConverter();

private slots:
