## ExcelToCsvConverter.cpp
```cpp
#include "ExcelToCsvConverter.h"
#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QPushButton>
#include <QLabel>
#include <QTextEdit>
#include <QProgressBar>
#include <QFileDialog>
#include <QMessageBox>
#include <QDir>
#include <QDirIterator>
#include <QAxObject>
#include <QVariant>
#include <QDebug>
#include <QThread>

// ConversionWorker Implementation
ConversionWorker::ConversionWorker(const QString &dirPath) : m_dirPath(dirPath)
{
}

void ConversionWorker::process()
{
    emit log("Starting conversion process...");

    QDir dir(m_dirPath);
    QString csvFolderPath = m_dirPath + "/csv_output";

    // Create csv_output folder
    if (!dir.exists("csv_output")) {
        if (!dir.mkdir("csv_output")) {
            emit error("Failed to create csv_output folder");
            emit finished();
            return;
        }
    }

    emit log("Created/Using csv_output folder");

    // Find all Excel files
    QStringList filters;
    filters << "*.xlsx" << "*.xls" << "*.xlsm" << "*.xlsb";
    QDirIterator it(m_dirPath, filters, QDir::Files, QDirIterator::NoIteratorFlags);

    QStringList excelFiles;
    while (it.hasNext()) {
        excelFiles << it.next();
    }

    if (excelFiles.isEmpty()) {
        emit log("No Excel files found in the selected directory");
        emit finished();
        return;
    }

    emit log(QString("Found %1 Excel file(s)").arg(excelFiles.size()));

    int totalFiles = excelFiles.size();
    int processedFiles = 0;

    // Process each Excel file
    for (const QString &excelFile : excelFiles) {
        QFileInfo fileInfo(excelFile);
        QString csvFileName = fileInfo.baseName() + ".csv";
        QString csvFilePath = csvFolderPath + "/" + csvFileName;

        emit log(QString("Converting: %1").arg(fileInfo.fileName()));

        if (convertExcelToCsv(excelFile, csvFilePath)) {
            emit log(QString("✓ Successfully converted: %1").arg(fileInfo.fileName()));
        } else {
            emit log(QString("✗ Failed to convert: %1").arg(fileInfo.fileName()));
        }

        processedFiles++;
        int progressValue = (processedFiles * 100) / totalFiles;
        emit progress(progressValue);
    }

    emit log("Conversion process completed!");
    emit finished();
}

bool ConversionWorker::convertExcelToCsv(const QString &excelPath, const QString &csvPath)
{
    QAxObject *excel = new QAxObject("Excel.Application");
    if (!excel->isNull()) {
        excel->setProperty("Visible", false);
        excel->setProperty("DisplayAlerts", false);

        QAxObject *workbooks = excel->querySubObject("Workbooks");
        QAxObject *workbook = workbooks->querySubObject("Open(const QString&)", excelPath);

        if (workbook) {
            // Get the first worksheet
            QAxObject *worksheets = workbook->querySubObject("Worksheets");
            QAxObject *worksheet = worksheets->querySubObject("Item(int)", 1);

            if (worksheet) {
                // Save as CSV (FileFormat=6 for CSV)
                QVariant csvFormat(6);
                worksheet->dynamicCall("SaveAs(const QString&, int)", csvPath, csvFormat);

                delete worksheet;
            }

            workbook->dynamicCall("Close()");
            delete worksheets;
            delete workbook;
        }

        delete workbooks;
        excel->dynamicCall("Quit()");
        delete excel;

        return QFile::exists(csvPath);
    }

    delete excel;
    return false;
}

// ExcelToCsvConverter Implementation
ExcelToCsvConverter::ExcelToCsvConverter(QWidget *parent)
    : QMainWindow(parent), m_workerThread(nullptr)
{
    setupUi();
    setWindowTitle("Excel to CSV Converter");
    resize(600, 400);
}

ExcelToCsvConverter::~ExcelToCsvConverter()
{
    if (m_workerThread && m_workerThread->isRunning()) {
        m_workerThread->quit();
        m_workerThread->wait();
    }
}

void ExcelToCsvConverter::setupUi()
{
    QWidget *centralWidget = new QWidget(this);
    QVBoxLayout *mainLayout = new QVBoxLayout(centralWidget);

    // Directory selection section
    QHBoxLayout *dirLayout = new QHBoxLayout();
    m_selectButton = new QPushButton("Select Directory", this);
    m_pathLabel = new QLabel("No directory selected", this);
    m_pathLabel->setStyleSheet("QLabel { background-color: #f0f0f0; padding: 5px; border: 1px solid #ccc; }");

    dirLayout->addWidget(m_selectButton);
    dirLayout->addWidget(m_pathLabel, 1);

    // Convert button
    m_convertButton = new QPushButton("Convert Excel Files to CSV", this);
    m_convertButton->setEnabled(false);
    m_convertButton->setStyleSheet("QPushButton { padding: 10px; font-size: 14px; font-weight: bold; }");

    // Progress bar
    m_progressBar = new QProgressBar(this);
    m_progressBar->setRange(0, 100);
    m_progressBar->setValue(0);

    // Log output
    QLabel *logLabel = new QLabel("Conversion Log:", this);
    m_logOutput = new QTextEdit(this);
    m_logOutput->setReadOnly(true);

    // Add widgets to layout
    mainLayout->addLayout(dirLayout);
    mainLayout->addWidget(m_convertButton);
    mainLayout->addWidget(m_progressBar);
    mainLayout->addWidget(logLabel);
    mainLayout->addWidget(m_logOutput, 1);

    setCentralWidget(centralWidget);

    // Connect signals
    connect(m_selectButton, &QPushButton::clicked, this, &ExcelToCsvConverter::selectDirectory);
    connect(m_convertButton, &QPushButton::clicked, this, &ExcelToCsvConverter::startConversion);
}

void ExcelToCsvConverter::selectDirectory()
{
    QString dir = QFileDialog::getExistingDirectory(this, 
        "Select Directory Containing Excel Files",
        QString(),
        QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks);

    if (!dir.isEmpty()) {
        m_selectedDirectory = dir;
        m_pathLabel->setText(m_selectedDirectory);
        m_convertButton->setEnabled(true);
        m_logOutput->clear();
        m_progressBar->setValue(0);
    }
}

void ExcelToCsvConverter::startConversion()
{
    if (m_selectedDirectory.isEmpty()) {
        QMessageBox::warning(this, "Warning", "Please select a directory first.");
        return;
    }

    // Disable buttons during conversion
    m_selectButton->setEnabled(false);
    m_convertButton->setEnabled(false);
    m_progressBar->setValue(0);
    m_logOutput->clear();

    // Create worker thread
    m_workerThread = new QThread();
    ConversionWorker *worker = new ConversionWorker(m_selectedDirectory);
    worker->moveToThread(m_workerThread);

    // Connect signals
    connect(m_workerThread, &QThread::started, worker, &ConversionWorker::process);
    connect(worker, &ConversionWorker::finished, m_workerThread, &QThread::quit);
    connect(worker, &ConversionWorker::finished, worker, &QObject::deleteLater);
    connect(m_workerThread, &QThread::finished, m_workerThread, &QObject::deleteLater);

    connect(worker, &ConversionWorker::progress, this, &ExcelToCsvConverter::handleProgress);
    connect(worker, &ConversionWorker::log, this, &ExcelToCsvConverter::handleLog);
    connect(worker, &ConversionWorker::finished, this, &ExcelToCsvConverter::handleFinished);
    connect(worker, &ConversionWorker::error, this, &ExcelToCsvConverter::handleError);

    m_workerThread->start();
}

void ExcelToCsvConverter::handleProgress(int value)
{
    m_progressBar->setValue(value);
}

void ExcelToCsvConverter::handleLog(const QString &message)
{
    m_logOutput->append(message);
}

void ExcelToCsvConverter::handleFinished()
{
    m_selectButton->setEnabled(true);
    m_convertButton->setEnabled(true);
    QMessageBox::information(this, "Success", "Conversion completed! Check the csv_output folder.");
}

void ExcelToCsvConverter::handleError(const QString &error)
{
    m_selectButton->setEnabled(true);
    m_convertButton->setEnabled(true);
    QMessageBox::critical(this, "Error", error);
}
